<?php
declare(strict_types=1);require_once __DIR__ . '/config/product_step11.php';$error=null;$rows=[];$q=trim((string)($_GET['q']??''));try{$pdo=business_db();product_step11_ensure($pdo);$ctx=product_org_context($pdo);$orgId=(int)$ctx['organization_id'];$sql="SELECT p.id,p.sku,p.product_name,c.category_name,pv.id price_id,pv.effective_from,pv.effective_to,pv.mrp,pv.volume_points,pv.status FROM products p LEFT JOIN product_categories c ON c.id=p.category_id JOIN product_market_listings l ON l.product_id=p.id AND l.organization_id=p.organization_id JOIN product_price_versions pv ON pv.listing_id=l.id AND pv.organization_id=p.organization_id WHERE p.organization_id=?";$args=[$orgId];if($q!==''){$sql.=" AND (p.sku LIKE ? OR p.product_name LIKE ? OR c.category_name LIKE ?)";$like='%'.$q.'%';array_push($args,$like,$like,$like);}$sql.=" ORDER BY p.product_name,pv.effective_from DESC,pv.id DESC";$stmt=$pdo->prepare($sql);$stmt->execute($args);$rows=$stmt->fetchAll();}catch(Throwable $e){$error=$e->getMessage();}?>
