form method="get" class="pp-toolbar" style="grid-template-columns:1fr auto"><input name="q" value="<?= product_h($q) ?>" placeholder="Search Stock No., product or category"><button>Search</button></form><div class="pp-table-wrap"><table class="pp-table"><thead><tr><th>Stock</th><th>Product</th><th>Category</th><th>Effective From</th><th>Effective To</th><th>MRP</th><th>VP</th><th>Status</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><a href="product_detail.php?id=<?= (int)$r['id'] ?>"><b><?= product_h($r['sku']) ?></b></a></td><td><?= product_h($r['product_name']) ?></td><td><?= product_h($r['category_name']) ?></td><td><?= product_h($r['effective_from']) ?></td><td><?= product_h($r['effective_to']?:'Current') ?></td><td>₹<?= number_format((float)$r['mrp'],2) ?></td><td><?= product_h(rtrim(rtrim(number_format((float)$r['volume_points'],3,'.',''),'0'),'.')) ?></td><td><span class="pp-badge"><?= product_h($r['status']) ?></span></td></tr><?php endforeach;?></tbody></table></div></section><?php endif;?></main></div><script src="assets/business-collapsible.js?v=20260820-1" defer></script></body></html>
